package com.almaraama.shared.id;

import java.util.Objects;
import java.util.UUID;

/** Public identifier of a building (sites module), referenced by other modules (CF-2, CF-10). */
public record BuildingId(UUID value) {

    public BuildingId {
        Objects.requireNonNull(value, "value");
    }

    /** A new UUID v7 identifier, generated by the application (CF-10). */
    public static BuildingId newId() {
        return new BuildingId(UuidV7.next());
    }

    /** The UUID in its canonical text form. */
    @Override
    public String toString() {
        return value.toString();
    }
}
